BEGIN;
SELECT no_plan();
CREATE TEMP TABLE manual_ar_fixture(input jsonb, request_id uuid, result jsonb);
INSERT INTO manual_ar_fixture VALUES ('{"invoice_ref":"  Manual AR fixture  ","invoice_date":"2026-10-19","due_date":"2026-10-20","amount":4.10,"vat_rate":15}',gen_random_uuid(),NULL);
GRANT ALL ON manual_ar_fixture TO authenticated;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-0000-0000-000000000001","aal":"aal2"}',true);
UPDATE manual_ar_fixture SET result=public.create_manual_receivable_atomic(input,request_id);
SELECT is((SELECT result->>'replayed' FROM manual_ar_fixture),'false','first request commits a new record');
SELECT is((SELECT tenant_id FROM public.receivables WHERE id=(SELECT (result->>'id')::uuid FROM manual_ar_fixture)),'00000000-0000-0000-0000-000000000001'::uuid,'tenant comes from JWT');
SELECT is((SELECT created_by FROM public.receivables WHERE id=(SELECT (result->>'id')::uuid FROM manual_ar_fixture)),'00000000-0000-0000-0000-000000000001'::uuid,'actor comes from JWT');
SELECT is((SELECT invoice_ref FROM public.receivables WHERE id=(SELECT (result->>'id')::uuid FROM manual_ar_fixture)),'Manual AR fixture','reference is normalized');
SELECT is((SELECT vat_amount FROM public.receivables WHERE id=(SELECT (result->>'id')::uuid FROM manual_ar_fixture)),0.62::numeric,'half-halalah VAT rounds in base ten');
SELECT is((SELECT total_amount FROM public.receivables WHERE id=(SELECT (result->>'id')::uuid FROM manual_ar_fixture)),4.72::numeric,'stored total includes exact VAT');
SELECT is((SELECT count(*)::int FROM public.audit_log WHERE entity_id=(SELECT (result->>'id')::uuid FROM manual_ar_fixture) AND action='receivable_created'),1,'creation has one audit entry');
SELECT is((SELECT public.create_manual_receivable_atomic(input,request_id)->>'id' FROM manual_ar_fixture),(SELECT result->>'id' FROM manual_ar_fixture),'retry returns original ID');
SELECT is((SELECT public.create_manual_receivable_atomic(input,request_id)->>'replayed' FROM manual_ar_fixture),'true','retry is marked as replayed');
SELECT is((SELECT count(*)::int FROM public.audit_log WHERE entity_id=(SELECT (result->>'id')::uuid FROM manual_ar_fixture) AND action='receivable_created'),1,'retry does not duplicate audit');
SELECT throws_ok($$SELECT public.create_manual_receivable_atomic(input || '{"amount":5}',request_id) FROM manual_ar_fixture$$,'P0001','AR_RETRY: request identifier already used for different details','different payload cannot reuse request');
SELECT throws_ok($$SELECT public.create_manual_receivable_atomic(input || '{"tenant_id":"00000000-0000-0000-0000-000000000002"}',gen_random_uuid()) FROM manual_ar_fixture$$,'22023',NULL,'caller cannot supply tenant');
SELECT throws_ok($$SELECT public.create_manual_receivable_atomic(input || '{"amount":"4.10"}',gen_random_uuid()) FROM manual_ar_fixture$$,'22023',NULL,'numeric strings are rejected');
SELECT throws_ok($$SELECT public.create_manual_receivable_atomic(input || '{"amount":0.001}',gen_random_uuid()) FROM manual_ar_fixture$$,'22023',NULL,'zero after rounding is rejected');
SELECT throws_ok($$SELECT public.create_manual_receivable_atomic(input || '{"vat_rate":101}',gen_random_uuid()) FROM manual_ar_fixture$$,'22023',NULL,'invalid VAT rate is rejected');
SELECT throws_ok($$SELECT public.create_manual_receivable_atomic(input || '{"due_date":"2026-10-18"}',gen_random_uuid()) FROM manual_ar_fixture$$,'22023',NULL,'due date cannot precede invoice date');
SELECT throws_ok($$SELECT public.create_manual_receivable_atomic(input || '{"invoice_date":"2026-02-30"}',gen_random_uuid()) FROM manual_ar_fixture$$,'22008',NULL,'impossible calendar date is rejected');
SELECT throws_ok($$SELECT public.create_manual_receivable_atomic(input || '{"amount":9999999999,"vat_rate":15}',gen_random_uuid()) FROM manual_ar_fixture$$,'22003',NULL,'total overflow aborts creation');
SELECT throws_ok($$UPDATE public.receivables SET invoice_ref='bypass' WHERE id=(SELECT (result->>'id')::uuid FROM manual_ar_fixture)$$,'42501',NULL,'direct API update cannot bypass managed transaction');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-0000-0000-000000000001","aal":"aal1"}',true);
SELECT throws_ok($$SELECT public.create_manual_receivable_atomic(input,gen_random_uuid()) FROM manual_ar_fixture$$,'42501',NULL,'MFA is enforced at RPC boundary');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-0000-0000-000000000001","aal":"aal2"}',true);
RESET ROLE;
SELECT throws_ok($$UPDATE public.receivables SET request_id=gen_random_uuid() WHERE id=(SELECT (result->>'id')::uuid FROM manual_ar_fixture)$$,'P0001','AR_IDENTITY: receivable request identity is immutable','request identity is immutable');
CREATE FUNCTION pg_temp.fail_manual_ar_audit() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN IF NEW.action='receivable_created' THEN RAISE EXCEPTION 'synthetic AR audit fault'; END IF; RETURN NEW; END $$;
CREATE TRIGGER trg_manual_ar_test_audit BEFORE INSERT ON public.audit_log FOR EACH ROW EXECUTE FUNCTION pg_temp.fail_manual_ar_audit();
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.create_manual_receivable_atomic(input || '{"invoice_ref":"Atomic rollback fixture"}',gen_random_uuid()) FROM manual_ar_fixture$$,'P0001','synthetic AR audit fault','audit failure aborts the transaction');
RESET ROLE;
SELECT is((SELECT count(*)::int FROM public.receivables WHERE invoice_ref='Atomic rollback fixture'),0,'audit failure leaves no receivable');
DROP TRIGGER trg_manual_ar_test_audit ON public.audit_log;
UPDATE public.receivables SET paid_amount=1 WHERE id=(SELECT (result->>'id')::uuid FROM manual_ar_fixture);
SET LOCAL ROLE authenticated;
SELECT lives_ok($$SELECT public.create_manual_receivable_atomic(input,request_id) FROM manual_ar_fixture$$,'payment updates do not invalidate creation retry');
RESET ROLE;
UPDATE public.receivables SET deleted_at=now() WHERE id=(SELECT (result->>'id')::uuid FROM manual_ar_fixture);
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.create_manual_receivable_atomic(input,request_id) FROM manual_ar_fixture$$,'P0001','AR_RETRY_UNAVAILABLE: original receivable needs review','deleted record cannot be reported as saved');
RESET ROLE;
SET LOCAL ROLE anon;
SELECT throws_ok($$SELECT public.create_manual_receivable_atomic('{}',gen_random_uuid())$$,'42501',NULL,'anonymous RPC denied');
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT throws_ok($$SELECT public.create_manual_receivable_atomic('{}',gen_random_uuid())$$,'42501',NULL,'service caller cannot impersonate JWT actor');
RESET ROLE;
SELECT * FROM finish();
ROLLBACK;
